            optionButtons = { x = 12, y = 80, width = 676, height = 28, gap = 6,
                bottom = 14, icon = 18, iconX = 10, labelX = 36, rightPad = 14,
                minWidth = 160, cardMinWidth = 350 },
        },
        quest = {
            hideBody = true,
            hideRole = true,
            -- The NPC name and the quest title 3 pixels lower than the
