            speaker = { 76, 15 + 3 / Client.QUEST_DIALOGUE_BASE_UNIT, 420, 20 },
            title = { 76, 37 + 3 / Client.QUEST_DIALOGUE_BASE_UNIT, 420, 18 },
            -- The "!" / "?" badge alone, without its "Quest" label, under
